%% Plot impedance results generated by calculate_complex_impedance.m
% This script is intentionally separate from the impedance calculation.
% It creates the four representations used in the original working script:
% 1) Real impedance vs frequency
% 2) Capacitance vs frequency
% 3) Nyquist plot (Real Z vs -Imaginary Z)
% 4) Negative imaginary impedance vs frequency

clear;
clc;

%% Select the processed impedance file
projectRoot = fileparts(fileparts(fileparts(mfilename('fullpath'))));
processedDirectory = fullfile(projectRoot, 'data', 'processed');
figureDirectory = fullfile(projectRoot, 'results', 'figures', 'impedance');
if ~exist(figureDirectory, 'dir')
    mkdir(figureDirectory);
end

[fileName, filePath] = uigetfile( ...
    {'*.csv', 'Processed impedance files (*.csv)'}, ...
    'Select a processed impedance file', processedDirectory);
if isequal(fileName, 0)
    error('No processed file was selected.');
end
processedFile = fullfile(filePath, fileName);
T = readtable(processedFile);

requiredVariables = {'Frequency_Hz','ImpedanceReal_Ohm', ...
    'ImpedanceImag_Ohm','Capacitance_F'};
for k = 1:numel(requiredVariables)
    if ~ismember(requiredVariables{k}, T.Properties.VariableNames)
        error('The processed file is missing the required column: %s', ...
            requiredVariables{k});
    end
end

frequency_Hz = T.Frequency_Hz;
Zreal_Ohm = T.ImpedanceReal_Ohm;
Zimag_Ohm = T.ImpedanceImag_Ohm;
capacitance_F = T.Capacitance_F;

[~, sampleLabel, ~] = fileparts(fileName);

%% 1. Real impedance vs frequency
fig1 = figure('Name', 'Real impedance vs frequency', 'Color', 'w');
semilogx(frequency_Hz, Zreal_Ohm, 'LineWidth', 1.6);
grid on;
xlabel('Frequency (Hz)');
ylabel('Real impedance, Re(Z) (\Omega)');
title(['Real impedance vs frequency - ', sampleLabel], 'Interpreter', 'none');
saveFigure(fig1, figureDirectory, [sampleLabel, '_real_impedance_vs_frequency']);

%% 2. Capacitance vs frequency
fig2 = figure('Name', 'Capacitance vs frequency', 'Color', 'w');
semilogx(frequency_Hz, -capacitance_F, 'LineWidth', 1.6);
grid on;
xlabel('Frequency (Hz)');
ylabel('Negative capacitance convention, -C (F)');
title(['Capacitance vs frequency - ', sampleLabel], 'Interpreter', 'none');
saveFigure(fig2, figureDirectory, [sampleLabel, '_capacitance_vs_frequency']);

%% 3. Complex impedance plane (Nyquist representation)
fig3 = figure('Name', 'Nyquist impedance plot', 'Color', 'w');
plot(Zreal_Ohm, -Zimag_Ohm, 'LineWidth', 1.6);
grid on;
axis equal;
xlabel('Real impedance, Re(Z) (\Omega)');
ylabel('Negative imaginary impedance, -Im(Z) (\Omega)');
title(['Nyquist plot - ', sampleLabel], 'Interpreter', 'none');
saveFigure(fig3, figureDirectory, [sampleLabel, '_nyquist']);

%% 4. Negative imaginary impedance vs frequency
fig4 = figure('Name', 'Negative imaginary impedance vs frequency', 'Color', 'w');
semilogx(frequency_Hz, -Zimag_Ohm, 'LineWidth', 1.6);
grid on;
xlabel('Frequency (Hz)');
ylabel('Negative imaginary impedance, -Im(Z) (\Omega)');
title(['Negative imaginary impedance vs frequency - ', sampleLabel], ...
    'Interpreter', 'none');
saveFigure(fig4, figureDirectory, [sampleLabel, '_negative_imaginary_impedance_vs_frequency']);

fprintf('Four impedance figures saved to: %s\n', figureDirectory);

%% Local figure-export function
function saveFigure(figHandle, outputDirectory, baseName)
    savefig(figHandle, fullfile(outputDirectory, [baseName, '.fig']));
    print(figHandle, fullfile(outputDirectory, [baseName, '.png']), '-dpng', '-r300');
end
